import org.springframework.kafka.annotation.KafkaListener;

// ❌ OLD: Default auto-commit. The offset is committed periodically
// regardless of whether processing succeeded. If process() throws,
// the record is LOST (the offset already advanced) — no retry, no
// dead-letter, and crashes between poll and commit cause reprocessing
// (at-least-once). For a payment/order system, silently dropping a
// failed message is a data-integrity bug.
public class OrderListenerLegacy {
  @KafkaListener(topics = "orders", groupId = "order-svc")
  public void onOrder(Order order) {
    process(order); // ❌ OLD: if this throws, the message is effectively lost
  }
}

