import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.annotation.RetryableTopic;
import org.springframework.kafka.support.Acknowledgment;

// ✅ NEW: Manual acknowledgement + retryable topics give control over
// delivery semantics.
public class OrderListener {
  // ✅ NEW: retries go to -retry topics, then a dead-letter topic after
  // max attempts — no silent message loss.
  @RetryableTopic(attempts = "4", autoCreateTopics = "true")
  @KafkaListener(topics = "orders", groupId = "order-svc")
  public void onOrder(Order order, Acknowledgment ack) {
    try {
      process(order); // ✅ NEW: business logic
      ack.acknowledge(); // ✅ NEW: commit offset only after success
    } catch (Exception e) {
      // exception propagates → retry / dead-letter per @RetryableTopic
      throw e;
    }
  }
}

// Configuration: spring.kafka.listener.ack-mode=MANUAL
// This gives at-least-once WITH retries — a failed record is retried
// and ultimately parked in a dead-letter topic instead of being lost.
